head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
		scwin.simulateWrapper = function(target, type, options) {
			WebSquare.wUnit.getJq(target).simulate(type, options);
		}
		scwin.setSimulate1 = function() {
			scwin.simulateWrapper('#gridView1_cell_0_1', 'key-combo', {
				combo: 'down-arrow'
			});
		}
		scwin.setSimulate2 = function() {
			scwin.simulateWrapper('#gridView1_cell_0_4', 'key-combo', {
				combo: 'right-arrow'
			});
		}		
		scwin.setSimulate3 = function() {
			scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
				combo: 'left-arrow'
			});
		}
		scwin.setSimulate4 = function() {
			scwin.simulateWrapper('#gridView1_cell_0_0', 'key-combo', {
				combo: 'right-arrow'
			});
		}				
scwin.checkVal1 = function() {
	return WebSquare.wUnit.getJq('#G_'+$p.id+'gridView1__col7').is(':visible') == true;
}
scwin.checkVal2 = function() {
	return WebSquare.wUnit.getJq('#G_'+$p.id+'gridView1__col7').is(':visible') == true;
}
scwin.checkVal3 = function() {
	return WebSquare.wUnit.getJq('#gridView1_cell_0_1').is(':focus');
}

scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");

    //WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate4()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    for (var i = 0; i < 5; i++) {
        dataList1.insertRow();
    }
    dataList1.setCellData(0, 0, "abc");
    gridView1.setColumnReadOnly("col2", true);
    gridView1.setColumnReadOnly("col3", true);
    gridView1.setColumnReadOnly("col4", true);
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 02-Apr-2018
    //end
}
